using HastaneRandevuSistemi.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace HastaneRandevuSistemi.Controllers;[Authorize(Roles="Müdür")]public class ManagerController:Controller{readonly HospitalContext db;public ManagerController(HospitalContext d)=>db=d;public async Task<IActionResult> Index(){ViewBag.UserCount=await db.Users.CountAsync();ViewBag.DoctorCount=await db.Doctors.CountAsync();ViewBag.PatientCount=await db.Patients.CountAsync();ViewBag.AppointmentCount=await db.Appointments.CountAsync();ViewBag.BranchCount=await db.Branches.CountAsync();return View(await db.Appointments.Include(x=>x.Patient).ThenInclude(x=>x.User).Include(x=>x.Doctor).ThenInclude(x=>x.User).Include(x=>x.Doctor).ThenInclude(x=>x.Branch).OrderByDescending(x=>x.AppointmentDate).ToListAsync());}}
